const items = $input.all();
const item = items[0]?.json || {};

// Determine if trigger was Webhook or Cron Schedule
let eventType = 'WAITLIST_PROMOTION'; // Default for scheduled heartbeat

if (item.body && item.body.event_type) {
  eventType = item.body.event_type.toUpperCase();
} else if (item.event_type) {
  eventType = item.event_type.toUpperCase();
} else if (item.action) {
  eventType = item.action.toUpperCase();
}

const payload = item.body || item;

return [{
  json: {
    event_type: eventType,
    flight_id: payload.flight_id || null,
    flight_number: payload.flight_number || null,
    pnr: payload.pnr || null,
    customer_email: payload.customer_email || payload.recipient_email || 'customer@flightsystem.com',
    message: payload.message || 'Automated Pipeline Trigger',
    triggered_at: new Date().toISOString()
  }
}];

const items = $input.all();
if (!items.length || !items[0].json.waitlist_id) return [];
const token = 'CLAIM-' + Math.random().toString(36).substring(2, 10).toUpperCase();
const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
return [{ json: { ...items[0].json, claim_token: token, claim_expires_at: expiresAt } }];

